    idx = [j for k in range(d + 1) for j in it.combinations_with_replacement(range(x.shape[1]), k)]
    return (np.stack([np.prod(x[:, j], axis=1) for j in idx], axis=1), idx)

def cv(M, Y, folds):
    e = []
    for valid in folds:
        fit = np.setdiff1d(np.arange(len(Y)), valid)
        e.append(np.mean(np.abs(M[valid] @ np.linalg.lstsq(M[fit], Y[fit], rcond=None)[0] - Y[valid])))
    return np.round(e, 5)

